{
  "root": "main_stack",
  "state": {
    "itineraryDays": [
      {
        "day": "Day 1",
        "date": "September 10th",
        "morning": "Arrive in London, check into your accommodation, and settle in.",
        "afternoon": "Experience panoramic views of the city from the London Eye. Follow with a relaxing Thames River cruise for a unique perspective of London's landmarks.",
        "food": "Casual dinner at a family-friendly restaurant along the South Bank.",
        "actionLabel": "Book London Eye",
        "actionUrl": "https://www.londoneye.com/tickets-and-prices/",
        "icon": "../assets/r_000374_01_3_geo-alt.svg"
      },
      {
        "day": "Day 2",
        "date": "September 11th",
        "morning": "Explore the historic Tower of London, home to the Crown Jewels and Yeoman Warder tours.",
        "afternoon": "Discover the fascinating history of Tower Bridge with its exhibition and glass floor walkway. Afterwards, immerse yourselves in the vibrant atmosphere and diverse food stalls of Borough Market.",
        "food": "Enjoy delicious street food at Borough Market or a traditional pub lunch nearby.",
        "actionLabel": "Tower of London Tickets",
        "actionUrl": "https://www.hrp.org.uk/tower-of-london/",
        "icon": "../assets/r_000374_01_2_building.svg"
      },
      {
        "day": "Day 3",
        "date": "September 12th",
        "morning": "Visit the British Museum to marvel at ancient artifacts, including the Rosetta Stone and Egyptian mummies (free entry).",
        "afternoon": "Wander through the lively streets of Covent Garden, enjoying street performers and browsing unique shops.",
        "food": "Dine at a family-friendly restaurant in Covent Garden, offering a variety of cuisines.",
        "actionLabel": null,
        "actionUrl": null,
        "icon": "../assets/r_000391_01_6_book.svg"
      },
      {
        "day": "Day 4",
        "date": "September 13th",
        "morning": "Explore the Natural History Museum, famous for its dinosaur exhibits and impressive architecture (free entry).",
        "afternoon": "Head to the adjacent Science Museum for interactive exhibits that engage all ages (free entry). Afterwards, relax and let the kids play in Hyde Park.",
        "food": "Grab a meal at a museum cafe or a family restaurant in South Kensington.",
        "actionLabel": null,
        "actionUrl": null,
        "icon": "../assets/r_000379_01_3_tree.svg"
      },
      {
        "day": "Day 5",
        "date": "September 14th",
        "morning": "Witness the iconic Changing of the Guard ceremony at Buckingham Palace (check schedule in advance).",
        "afternoon": "Stroll through the beautiful St. James's Park, then view Westminster Abbey and the Houses of Parliament from the exterior.",
        "food": "Experience a classic British pub for dinner, many offer kid-friendly options.",
        "actionLabel": "Changing of Guard Schedule",
        "actionUrl": "https://www.householddivision.org.uk/changing-the-guard-calendar",
        "icon": "../assets/r_000374_01_1_house.svg"
      },
      {
        "day": "Day 6",
        "date": "September 15th",
        "morning": "Travel to Hampton Court Palace (approximately 40 minutes by train from central London). Explore the magnificent palace, its famous maze, and extensive gardens.",
        "afternoon": "Continue to immerse yourselves in the history and beauty of the palace, enjoying the various exhibitions and activities suitable for families.",
        "food": "Have lunch at one of the cafes within Hampton Court Palace or explore dining options in nearby Kingston upon Thames.",
        "actionLabel": "Hampton Court Tickets",
        "actionUrl": "https://www.hrp.org.uk/hampton-court-palace/",
        "icon": null
      },
      {
        "day": "Day 7",
        "date": "September 16th",
        "morning": "Enjoy a leisurely morning at Regent's Park, which offers beautiful gardens, a boating lake, and excellent children's playgrounds. Consider a visit to London Zoo located within the park if time allows.",
        "afternoon": "Do some last-minute souvenir shopping or revisit a favorite spot. Head to the airport for your departure.",
        "food": "Enjoy a final farewell lunch near your accommodation before heading home.",
        "actionLabel": null,
        "actionUrl": null,
        "icon": "../assets/r_000386_01_1_cloud-sun.svg"
      }
    ]
  },
  "elements": {
    "main_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "md"
      },
      "children": [
        "title",
        "intro_text",
        "itinerary_table",
        "planning_context_heading",
        "planning_context_transport",
        "planning_context_booking",
        "planning_context_flexibility",
        "quick_actions_heading",
        "quick_action_tfl_button",
        "quick_action_attractions_button",
        "sources_heading",
        "source_tfl_button",
        "source_visitlondon_button",
        "source_hrp_button",
        "source_household_button"
      ]
    },
    "title": {
      "type": "Text",
      "props": {
        "text": "London Family Adventure: 7-Day Itinerary",
        "variant": "h2"
      },
      "children": []
    },
    "intro_text": {
      "type": "Text",
      "props": {
        "text": "This itinerary outlines a 7-day family trip to London, UK, from September 10th to 17th, 2024, for two adults and two children (ages 8 and 12). The plan focuses on historical sites, interactive museums, and family-friendly parks, maintaining a moderate pace with free time. The suggested budget of £3000 for activities, food, and local transport for the week is achievable by balancing paid attractions with free museums and park visits, alongside moderate dining choices."
      },
      "children": []
    },
    "itinerary_table": {
      "type": "Table",
      "props": {
        "columns": [
          {
            "key": "day",
            "label": "Day"
          },
          {
            "key": "date",
            "label": "Date"
          },
          {
            "key": "morning",
            "label": "Morning"
          },
          {
            "key": "afternoon",
            "label": "Afternoon"
          },
          {
            "key": "food",
            "label": "Food"
          },
          {
            "key": "actionLabel",
            "label": "Action"
          },
          {
            "key": "icon",
            "label": "Icon"
          }
        ],
        "statePath": "/itineraryDays",
        "domain": "schedule",
        "preferredPresentation": "cards",
        "primaryColumn": "day",
        "highlightColumns": [
          "morning",
          "afternoon"
        ]
      },
      "children": []
    },
    "planning_context_heading": {
      "type": "Text",
      "props": {
        "text": "Planning Context",
        "variant": "h3"
      },
      "children": []
    },
    "planning_context_transport": {
      "type": "Text",
      "props": {
        "text": "Local Transport: Consider purchasing a 7-day Oyster Card or Travelcard upon arrival for convenient and cost-effective travel on London's extensive public transport network (Underground, buses, DLR, Overground)."
      },
      "children": []
    },
    "planning_context_booking": {
      "type": "Text",
      "props": {
        "text": "Booking: For popular attractions like the London Eye, Tower of London, and Hampton Court Palace, it is highly recommended to book tickets in advance online to secure your preferred time slots and often save money."
      },
      "children": []
    },
    "planning_context_flexibility": {
      "type": "Text",
      "props": {
        "text": "Flexibility: This itinerary provides a framework; feel free to adjust it based on your family's energy levels and specific interests. London has many free museums and parks that can be easily substituted or added."
      },
      "children": []
    },
    "quick_actions_heading": {
      "type": "Text",
      "props": {
        "text": "Quick Actions",
        "variant": "h3"
      },
      "children": []
    },
    "quick_action_tfl_button": {
      "type": "Button",
      "props": {
        "label": "Plan Your Journey with TfL"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://tfl.gov.uk/plan-a-journey/"
          }
        }
      },
      "children": []
    },
    "quick_action_attractions_button": {
      "type": "Button",
      "props": {
        "label": "Explore More London Attractions"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.visitlondon.com/things-to-do/"
          }
        }
      },
      "children": []
    },
    "sources_heading": {
      "type": "Text",
      "props": {
        "text": "Sources",
        "variant": "h3"
      },
      "children": []
    },
    "source_tfl_button": {
